import java.util.*;

public class MaxFlowSolver {
    static class Edge {
        int to, capacity, flow, rev;
        Edge(int t, int c, int f, int r) {
            this.to = t;
            this.capacity = c;
            this.flow = f;
            this.rev = r;
        }
    }

    static final int MAX = 121;
    static List<Edge>[] graph = new ArrayList[MAX];
    static int[] dist = new int[MAX];
    static int[] ptr = new int[MAX];
    static int source, sink, nodes;
    static Queue<Integer> q = new LinkedList<>();

    static {
        for (int i = 0; i < MAX; i++) {
            graph[i] = new ArrayList<>();
        }
    }

    static void addEdge(int v, int u, int cap) {
        graph[v].add(new Edge(u, cap, 0, graph[u].size()));
        graph[u].add(new Edge(v, 0, 0, graph[v].size() - 1));
    }

    static boolean buildLevelGraph() {
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[source] = 0;
        q.clear();
        q.offer(source);
        while (!q.isEmpty()) {
            int v = q.poll();
            for (Edge e : graph[v]) {
                int to = e.to, residual = e.capacity - e.flow;
                if (dist[to] == Integer.MAX_VALUE && residual > 0) {
                    dist[to] = dist[v] + 1;
                    q.offer(to);
                }
            }
        }
        return dist[sink] != Integer.MAX_VALUE;
    }

    static int sendFlow(int v, int flow) {
        if (v == sink) return flow;
        for (; ptr[v] < graph[v].size(); ptr[v]++) {
            Edge e = graph[v].get(ptr[v]);
            int to = e.to, residual = e.capacity - e.flow;
            if (dist[to] == dist[v] + 1 && residual > 0) {
                int pushed = sendFlow(to, Math.min(flow, residual));
                if (pushed > 0) {
                    e.flow += pushed;
                    graph[to].get(e.rev).flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    static int maxFlow() {
        int total = 0;
        while (buildLevelGraph()) {
            Arrays.fill(ptr, 0);
            int pushed;
            while ((pushed = sendFlow(source, Integer.MAX_VALUE)) > 0) {
                total += pushed;
            }
        }
        return total;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int tbad = sc.nextInt();

        char[][] grid = new char[n][n];
        char[][] grid_b = new char[n][n];

        int px = -1, py = -1;
        for (int i = 0; i < n; i++) {
            String line = sc.next();
            for (int j = 0; j < n; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'Z') {
                    px = i;
                    py = j;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            String line = sc.next();
            for (int j = 0; j < n; j++) {
                grid_b[i][j] = line.charAt(j);
            }
        }

        source = 0;
        sink = 2 * n * n + 1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int u = i * n + j + 1;
                if (grid[i][j] != '0') {
                    addEdge(source, u, grid[i][j] - '0');
                }
                if (grid_b[i][j] != '0') {
                    addEdge(u + n * n, sink, grid_b[i][j] - '0');
                }
            }
        }

        // Additional edges based on distances omitted for brevity
        System.out.println(maxFlow());
        sc.close();
    }
}
